  "roam.controls.legend": "Commandes",
  "roam.disclaimer": "<b>Pas privé — annoncé en clair.</b> Le QSY coordonné vous fait passer, vous et une autre station, sur un nouveau canal ensemble, le changement étant envoyé en texte clair (la Part 97 de la FCC interdit le chiffrement et le sens dissimulé, et votre indicatif vous identifie toutes les 10 min). Cela sème un scanner <em>occasionnel</em> resté sur l'ancienne fréquence — cela ne vous <em>cache</em> de personne disposant d'un récepteur large bande, qui peut suivre. À utiliser contre le QRM et pour une discrétion modeste, jamais pour le secret.",
