  "sat.lockOn.title": "Rejoue votre choix de transpondeur — route, règle la bande et le mode, écrit les deux voies et vous recentre dans la bande passante. À utiliser après avoir déplacé le VFO hors du transpondeur à la main, ou quand la radio est revenue ailleurs.",
  "sat.log.note": "Enregistre un contact ordinaire depuis votre VFO, exactement comme les panneaux de journal Phone et CW. Il n'est <b>pas</b> marqué comme QSO satellite : Nexus n'écrit pas encore les champs ADIF PROP_MODE et SAT_NAME, le contact ne compte donc ni pour le crédit satellite LoTW <b>ni pour vos propres totaux satellite dans Nexus</b>. Ajoutez vous-même les <b>deux</b> champs si vous voulez ce crédit — l'un sans l'autre est refusé à la signature, et sur 2 m le locator compterait sinon pour votre VUCC terrestre, qu'un contact satellite ne rapporte pas.",
  "sat.log.note.title": "Enregistre un contact ordinaire depuis votre VFO, exactement comme les panneaux de journal Phone et CW. Il n'est PAS marqué comme QSO satellite : Nexus n'écrit pas encore les champs ADIF PROP_MODE et SAT_NAME, le contact ne compte donc ni pour le crédit satellite LoTW ni pour vos propres totaux satellite dans Nexus. Ajoutez vous-même les DEUX champs si vous voulez ce crédit — l'un sans l'autre est refusé à la signature, et sur 2 m le locator compterait sinon pour votre VUCC terrestre, qu'un contact satellite ne rapporte pas.",
  "sat.noGrid": "Indiquez d'abord votre locator (Réglages ▸ Station) — les passages sont calculés au-dessus de VOTRE position, et sans locator il n'y a rien d'honnête à afficher.",
