  "settings.confirmations.hamqth.username.hint": "Un annuaire <b>gratuit</b> utilisé en repli quand QRZ n'est pas configuré ou ne trouve rien — un compte HamQTH renvoie le nom, le locator et l'État US sans frais. Enregistrer les réglages pour appliquer.",
