  "settings.contestCategory.journal.assisted": "assisté",
  "settings.contestCategory.journal.hint": "Conservé dans <code>assistance_journal.json</code> à côté de vos réglages, il survit aux redémarrages. Plus récent en premier.",
  "settings.contestCategory.journal.label": "Registre d'assistance",
  "settings.contestCategory.journal.noSources": "rien d'actif",
  "settings.contestCategory.journal.unassisted": "UNASSISTED",
  "settings.contestCategory.legend": "Catégorie de concours",
  "settings.contestCategory.unassisted.aria.declare": "Déclarer une participation non assistée",
  "settings.contestCategory.unassisted.aria.end": "Terminer une participation non assistée",
  "settings.contestCategory.unassisted.hint": "Désactive d'un coup le décodeur CW par IA, les spots DX cluster / RBN et le flux des manquants PSK Reporter, et enregistre le changement avec un horodatage. Effet immédiat. Vos réglages pour chacun d'eux restent intacts et reviennent quand vous désactivez ceci.",
  "settings.contestCategory.unassisted.label": "Participation non assistée",
  "settings.cw.idAfter73.hint": "Manipule votre indicatif en CW une fois le 73 final complètement parti (option WSJT-X d'origine, désactivée par défaut). Utilise la chaîne de manipulation CW normale — PTT + tonalité — après le passage FT8, jamais par-dessus.",
  "settings.cw.idAfter73.label": "ID CW après le 73",
  "settings.cw.keyLine.dtr": "DTR (la convention CW)",
  "settings.cw.keyLine.hint": "Quelle ligne de contrôle manipule la radio. DTR est la norme (RTS = PTT) ; passez à RTS si votre interface est câblée à l'inverse.",
  "settings.cw.keyLine.label": "Ligne de manipulation",
  "settings.cw.keyPort.hint": "L'adaptateur USB-série qui pilote votre interface de manipulation (Buxcomm, un câble DTR maison, …) branchée sur la prise KEY de la radio. Ce doit être un port SÉPARÉ du CAT. Mettez la radio en CW et sa prise clé sur manipulateur droit / bug. Une interface contenant une puce WinKey — Timewave Navigator, microHAM, un K1EL WinKeyer — ne manipule <b>pas</b> sur DTR : choisissez plutôt WinKeyer ci-dessus et donnez-lui le port CW de cet appareil.",
  "settings.cw.keyPort.label": "Port série de manipulation",
  "settings.cw.keyPort.placeholder": "{{example}} — l'interface de manipulation (distincte du CAT)",
  "settings.cw.keyer.cat": "CAT — la radio manipule le CW (Hamlib send_morse ; radios récentes uniquement)",
  "settings.cw.keyer.hint": "Comment Nexus envoie le CW. <b>CAT</b> utilise le manipulateur interne de la radio, mais les postes anciens (ex. IC-756PRO III) ne le gèrent pas. <b>Ligne série</b> bascule DTR/RTS vers la prise KEY (radio en CW, c'est elle qui met en forme le signal — la méthode propre de N1MM/fldigi, un simple câble de manipulation suffit). <b>WinKeyer</b> pilote un K1EL.<b>Carte son</b> manipule une tonalité audio — un contournement ; réglez l'excitation pour que l'ALC reste à zéro. <b>Cela sort votre radio du mode CW</b> vers un mode data (DATA-U/DATA-L, pour que la tonalité atteigne l'émetteur et non la prise micro), et le mode CW revient dès que vous choisissez un autre manipulateur. Commutable aussi en direct depuis le cockpit CW.",
  "settings.cw.keyer.label": "Mode de manipulation",
  "settings.cw.keyer.serial": "Ligne série (DTR/RTS) — manipule la prise KEY de la radio",
  "settings.cw.keyer.soundcard": "Carte son — tonalité audio via un mode data (contournement)",
  "settings.cw.keyer.unproven": "La manipulation CW par CAT <b>n'est pas éprouvée sur cette radio</b>. Son backend Hamlib envoie une commande de manipulation différente de celle utilisée sur les autres radios, et il annonce un succès dans les deux cas — donc si rien n'est émis, Nexus ne peut pas vous le dire. Si le CW ne sort pas, utilisez la ligne série, le WinKeyer ou la carte son.",
  "settings.cw.keyer.title": "Manipulateur",
  "settings.cw.keyer.winkeyer": "WinKeyer — manipulateur matériel K1EL",
  "settings.cw.legend": "CW",
  "settings.cw.macros.builtin.hint": "Jeu F1–F8 intégré en service. Personnalisez pour l'adapter (libellés + modèles ; jetons : {MYCALL} {RST} {NAME} et ! = l'indicatif contacté).",
