  "settings.features.fieldDay.hint": "À activer pour le week-end Field Day — fait apparaître l'espace Field Day, l'échange Classe/Section dans tous les modes, et l'onglet de configuration. Désactivé le reste de l'année (rien ne s'affiche). Reste actif au fil des redémarrages jusqu'à ce que vous le coupiez ; Enregistrer les réglages pour appliquer.",
