  "settings.fieldDay.category.hint": "Émetteurs + lieu : H=Home, I=Indoor, M=Mobile, O=Outdoor (ex. 2O = 2 émetteurs, extérieur).",
  "settings.fieldDay.category.label": "Catégorie WFD",
  "settings.fieldDay.class.hint": "Nombre d'émetteurs + lettre de classe : A=portable club/groupe, B=portable 1–2 personnes, C=mobile, D=domicile (secteur), E=domicile (alimentation de secours), F=EOC. Ex. 3A = 3 émetteurs, club portable.",
  "settings.fieldDay.class.label": "Classe FD",
  "settings.fieldDay.event.aria": "Événement Field Day",
  "settings.fieldDay.event.hint": "L'événement dans lequel vous trafiquez — agit sur les libellés de score et les en-têtes d'export.",
  "settings.fieldDay.event.label": "Événement",
