  "settings.fieldDay.mode.label": "Mode Field Day",
  "settings.fieldDay.needExchange": "<b>Renseignez votre Classe + Section pour commencer à trafiquer.</b> Le mode Field Day est actif, mais la station n'entrera pas en Field Day tant que les deux ne sont pas remplis ci-dessous.",
