  "settings.fdRules.empty": "Données de règles intégrées actives.",
  "settings.fdRules.hint": "Paramètres de score, fenêtres d\u2019événement, bonus et sections pour les deux événements Field Day. Vérification à la demande ; une mise à jour téléchargée s\u2019applique au prochain démarrage.",
  "settings.fdWho.legend": "Qui est qui à cet événement",
  "settings.fdWho.note": "Trois noms, trois rôles différents : l'indicatif du club part sur l'air, la position est la tente dans laquelle vous êtes assis, et l'opérateur est celui qui est au manipulateur en ce moment. En changer un ici le change partout dans Nexus : l'indicatif et l'opérateur sont les deux mêmes cases que l'onglet Station.",
  "settings.fdWho.call.label": "Indicatif émis",
  "settings.fdWho.call.hint": "L'indicatif qui part sur l'air et qui est inscrit sur chaque contact enregistré — lors d'un événement de club, c'est celui du club, le même à toutes les positions du site.",
  "settings.fdWho.position.label": "Nom de la position",
  "settings.fdWho.position.placeholder": "Tente CW",
  "settings.fdWho.position.hint": "Quelle tente, quelle remorque ou quelle table est cette station — ce nom vous désigne sur le tableau des bandes du club, pour que chacun voie quelle position est sur quelle bande, et il ne part jamais sur l'air.",
  "settings.fdWho.operator.label": "Opérateur au poste",
  "settings.fdWho.operator.placeholder": "vide = l'indicatif ci-dessus",
  "settings.fdWho.operator.hint": "Celui qui tient cette position en ce moment — à changer chaque fois que quelqu'un prend le poste ; ses contacts en sont marqués (ADIF OPERATOR) pour que le club puisse répartir le log par opérateur ensuite.",
  "settings.fdClub.legend": "Synchro de club Field Day",
  "settings.fdClub.host.label": "Héberger un événement de club",
  "settings.fdClub.host.hint": "Fusionne les contacts de toutes les positions en un journal de club sur ce PC — et ouvre un port sur le réseau local (la seule fois où Nexus écoute au-delà de cet ordinateur).",
  "settings.fdClub.host.note": "Les positions de ce réseau peuvent maintenant trouver et rejoindre cet événement. Pas de mot de passe — le LAN du site est de confiance, et quiconque s'y trouve pourrait ajouter des lignes au journal du club, ce qui restera visible. Si ce PC tombe, activez l'hébergement sur n'importe quelle autre position : tout le monde se reconnecte, rien n'est perdu.",
  "settings.fdClub.host.aria.enable": "Activer l'hébergement de l'événement de club",
  "settings.fdClub.host.aria.disable": "Désactiver l'hébergement de l'événement de club",
  "settings.fdClub.eventName.label": "Nom de l'événement",
  "settings.fdClub.eventName.placeholder": "W9ABC Field Day",
  "settings.fdClub.eventName.hint": "Affiché aux positions qui rejoignent et lors de la découverte.",
  "settings.fdClub.hostPort.label": "Port de l'hôte",
  "settings.fdClub.hostPort.hint": "Port TCP de la synchro du club (42073 par défaut).",
  "settings.fdClub.join.label": "Rejoindre l'événement à",
  "settings.fdClub.join.hint": "hôte:port de l'hôte du club — utilisez Trouver les événements du club, ou recopiez-le depuis l'écran de l'hôte.",
  "settings.fdClub.join.hostingHint": "Hébergement actif — cette position rejoint son propre événement automatiquement.",
