  "settings.fdClub.discover.empty": "Rien entendu en 2 s — même réseau ? Certains Wi-Fi bloquent la découverte ; saisissez l'adresse de l'hôte.",
  "settings.fdClub.discover.pick.label": "{{event}} — {{host}}",
  "settings.fdClub.discover.pick.title": "Utiliser {{host}} comme adresse de connexion",
  "settings.connectWeb.legend": "Connect sur un téléviseur",
  "settings.connectWeb.label": "Diffuser Connect sur ce réseau",
  "settings.connectWeb.hint": "Ouvre une page en lecture seule que tout navigateur du réseau peut afficher : téléviseur du shack, tablette, téléphone. Rien ne peut y être modifié.",
  "settings.connectWeb.exposes": "Tant que ceci est actif, toute personne sur votre réseau voit votre indicatif, votre locator et les conditions de bande. Votre journal, votre liste de besoins et la fréquence utilisée ne sont jamais transmis.",
  "settings.connectWeb.aria.enable": "Diffuser Connect sur le réseau local",
  "settings.connectWeb.aria.disable": "Arrêter de diffuser Connect sur le réseau local",
