  "settings.fdBoard.label": "Tableau des scores spectateurs",
  "settings.fdBoard.hint": "Sert une page de tableau des scores en lecture seule pour un téléviseur ou un projecteur sur ce réseau — rien à installer sur le téléviseur, et les spectateurs ne peuvent que regarder. La première activation peut déclencher une invite du pare-feu Windows ; autorisez-la, sinon les spectateurs ne verront rien.",
