  "settings.fdBoard.hostOnly": "Les données en direct apparaissent quand cette position héberge l’événement du club ; sinon la page renvoie les spectateurs vers l’hôte.",
  "settings.fieldDay.power.hundred.hint": "100W ou moins, quelle que soit la source",
  "settings.fieldDay.power.hundred.label": "×2 ≤100W",
  "settings.fieldDay.power.label": "Multiplicateur de puissance",
  "settings.fieldDay.power.qrp.hint": "Fonctionne entièrement sur batterie ou autre source naturelle, sortie ≤5W",
  "settings.fieldDay.power.qrp.label": "×5 QRP / batterie",
  "settings.fieldDay.section.hint": "Votre section ARRL / RAC (ex. WI, ENY, ONN). Tapez le code ou un nom d'État et choisissez dans la liste — validé sur les {{count}} sections. Obligatoire pour le journal Cabrillo.",
  "settings.fieldDay.section.invalid": "« {{section}} » n'est pas une section ARRL/RAC connue — choisissez-en une dans la liste.",
  "settings.fieldDay.section.label": "Section ARRL",
  "settings.fst4.hint": "<b>FST4</b> est le mode QSO ; <b>FST4W</b> est le mode balise façon WSPR — le choix se fait sur le sélecteur de tier. Nexus décode les deux et n'émet ni l'un ni l'autre. Les indicatifs hachés FST4W s'affichent en <code><...></code> : en amont, la table de correspondance se remplit depuis un fichier que cette version n'embarque pas.",
  "settings.fst4.legend": "FST4 (QSO) / FST4W (balise)",
  "settings.fst4.period.deepest": "1800 s — le plus profond",
  "settings.fst4.period.hint": "Commune aux deux tiers. Des périodes plus longues entendent des signaux plus faibles, au prix de moins d'échanges par heure. Les balises FST4W tournent en 120/300/900/1800 s ; le trafic QSO FST4 se fait plutôt en 15–60 s. Les deux stations (ou la balise que vous cherchez) doivent utiliser la même période.",
  "settings.fst4.period.label": "Période T/R",
  "settings.fst4.period.shortestBeacon": "120 s — intervalle balise FST4W le plus court",
  "settings.headphoneMonitor.device.hint": "Votre casque ou vos haut-parleurs — ce ne doit PAS être le périphérique de sortie TX de la radio.",
  "settings.headphoneMonitor.device.label": "Casque ou haut-parleurs",
  "settings.headphoneMonitor.enable.aria": "Écouter l'audio de réception sur cet ordinateur",
  "settings.headphoneMonitor.enable.hint": "Sort l'audio REÇU — exactement ce que le décodeur entend — sur un périphérique de cet ordinateur, pour diagnostiquer les niveaux et la RFI ou simplement écouter la bande. Ce n'est pas une écoute d'émission : votre propre voix n'est jamais renvoyée. Désactivé par défaut ; NON VÉRIFIÉ sur l'air tant que la session en présence n'a pas eu lieu.",
  "settings.headphoneMonitor.enable.label": "Écouter l'audio de réception ici",
