  "settings.headphoneMonitor.level.label": "Niveau d'écoute",
  "settings.integrations.allTxt.hint": "Journal de décodage au format WSJT-X, que GridTracker et les logiciels de journal peuvent suivre. Écrit uniquement quand ceci est actif, et il n'apparaît qu'après le décodage suivant.",
  "settings.integrations.allTxt.label": "Écrire le journal de décodage ALL.TXT",
