  "settings.integrations.saveWav.decodes": "Périodes avec décodages",
  "settings.integrations.saveWav.hint": "Les WAV atterrissent dans recordings/periods (12 kHz mono, ~360 KB chacun). « Toutes » écrit ~2 GB/jour en écoute continue — à réserver au débogage du décodeur, pas en permanence.",
