  "settings.jt65.hint": "Le mode classique des signaux faibles et du rebond lunaire, décodé et émis. Les messages sont au format ancien de 22 caractères, pas celui de 37 caractères qu'utilisent FT8 et consorts.",
  "settings.jt65.legend": "JT65 — EME classique",
  "settings.jt65.submode.a": "A — standard HF, le plus étroit",
  "settings.jt65.submode.b": "B — écart ×2",
  "settings.jt65.submode.c": "C — écart ×4, le plus tolérant au Doppler",
  "settings.jt65.submode.hint": "JT65 utilise toujours une période T/R de 60\\u00a0s, l'écart est donc le seul choix. A est ce qu'il vous faut en HF ; les opérateurs EME montent en B ou C quand l'étalement Doppler des bandes hautes brouille les tons. Les deux stations doivent utiliser le même sous-mode.",
  "settings.jt65.submode.label": "Sous-mode (écart des tons)",
  "settings.lotwUsers.empty": "Pas encore récupérée — les listes de décodages affichent un L sur les indicatifs qui envoient vers LoTW.",
