  "settings.lotwUsers.fetch.busy": "Récupération…",
  "settings.lotwUsers.fetch.done": "Liste LoTW chargée — {{count}} indicatifs",
  "settings.lotwUsers.fetch.failed": "Échec de la récupération de la liste LoTW : {{detail}}",
  "settings.lotwUsers.legend": "Liste des utilisateurs LoTW",
  "settings.lotwUsers.maxAge.hint": "La liste d'activité de l'ARRL est mise à jour chaque semaine — la récupérer plus souvent renvoie juste \"inchangé\". Récupération manuelle par choix (convention WSJT-X).",
  "settings.lotwUsers.maxAge.label": "Compter comme utilisateur LoTW si envoi depuis moins de (jours)",
  "settings.lotwUsers.status": "{{count}} indicatifs · récupérée {{date}}",
  "settings.msk144.hint": "MSK144 émet pendant presque toute la période, envoyant des centaines de fois la même trame de 72 ms — c'est ainsi que fonctionne le meteor scatter, et un contact peut demander de longues minutes de silence apparent. La fréquence audio est fixée sur un centre de 1500 Hz ; le signal fait 1 kHz de large, il n'y a donc nulle part où l'accorder. Les messages abrégés (MSK40) sont désactivés, comme par défaut dans WSJT-X.",
  "settings.msk144.legend": "MSK144 — meteor scatter",
  "settings.msk144.period.fast": "5 s — échanges rapides, grosses pluies",
  "settings.msk144.period.hint": "MSK144 envoie un message de 72\\u00a0ms encore et encore, si bien qu'une seule traînée de météore d'un dixième de seconde peut le porter en entier. Les périodes courtes bouclent l'échange plus vite pendant une pluie ; les longues donnent au décodeur plus de trames à empiler quand les pings sont rares. Les deux stations doivent utiliser la même période.",
  "settings.msk144.period.label": "Période T/R",
  "settings.msk144.period.sparse": "30 s — pings rares, plus à empiler",
  "settings.msk144.period.standard": "15 s — le standard 6 m",
  "settings.n1mm.addr.hint": "Où partent les paquets de contact N1MM (hôte:port, UDP). Précisez le port — les consommateurs s'empilent sur un même hôte, et 12060 est souvent déjà pris par un autre logiciel de journal. Laissez vide pour désactiver.",
  "settings.n1mm.addr.idle": "Une adresse seule n'envoie rien en dehors d'un événement Field Day — activez Diffuser chaque QSO ci-dessous pour le trafic de tous les jours.",
  "settings.n1mm.addr.label": "Adresse de diffusion des contacts N1MM",
  "settings.n1mm.addr.placeholder": "{{example}} (vide = désactivé)",
  "settings.n1mm.addr.sending": "Envoi à chaque QSO enregistré.",
  "settings.n1mm.broadcastAll.hint": "Envoie le paquet de contact pour <b>chaque</b> QSO enregistré, pas seulement en Field Day — pointez OpenHamClock ou GridTracker vers l'adresse ci-dessus et chaque contact se place sur leur carte au moment où vous l'enregistrez. Un paquet par QSO : cela ne fait jamais doublon avec la diffusion Field Day, vous pouvez donc le laisser activé pendant un événement. Désactivé par défaut ; désactivé, les paquets ne sortent <em>que</em> pendant un événement Field Day.",
  "settings.n1mm.broadcastAll.label": "Diffuser chaque QSO",
  "settings.n1mm.legend": "Intégration N1MM+",
  "settings.n3fjp.forwardAll.hint": "Envoie aussi <b>chaque</b> QSO enregistré (pas seulement Field Day) vers N3FJP ACLog sur l'hôte ci-dessus — le trafic de tous les jours. N3FJP déduplique, c'est donc sans risque en parallèle de l'envoi Field Day.",
  "settings.n3fjp.forwardAll.label": "Transmettre chaque QSO",
  "settings.n3fjp.host.hint": "IP ou nom d'hôte de l'ordinateur du journal maître. Laissez vide pour désactiver.",
  "settings.n3fjp.host.label": "Hôte N3FJP",
  "settings.n3fjp.host.placeholder": "{{example}} (vide = désactivé)",
  "settings.n3fjp.legend": "Intégration N3FJP (journal maître du club)",
  "settings.n3fjp.note": "Chaque contact FD arrive dans le <b>N3FJP Field Day Contest Log</b> du club dès que vous l'enregistrez — le score de tout le club se met donc à jour en temps réel. Faites tourner N3FJP sur l'ordinateur maître ; pointez Nexus vers son IP + port (1100 par défaut).",
  "settings.n3fjp.port.hint": "Le port TCP de l'API N3FJP (1100 par défaut).",
  "settings.n3fjp.port.label": "Port N3FJP",
  "settings.n3fjp.reportBand.hint": "Indique à N3FJP la bande sur laquelle vous êtes (sans CAT), pour que le tableau des bandes du Network Status Display du club affiche ce poste. Désactivé par défaut.",
  "settings.n3fjp.reportBand.label": "Signaler ma bande à N3FJP",
  "settings.n3fjp.test.action": "Tester N3FJP",
  "settings.n3fjp.test.hint": "À lancer sur le site du club avant le début de l'événement pour confirmer que le lien API fonctionne.",
  "settings.n3fjp.test.label": "Test de connexion",
  "settings.n3fjp.test.title": "Enregistrer les réglages, puis tester la connexion TCP N3FJP",
  "settings.n3fjp.useEnter.hint": "Enregistre chaque contact FD avec la séquence <b>ENTER</b> de N3FJP, celle qui compte les points — la bonne méthode. Désactivez pour retomber sur un simple <code>ADDDIRECT</code> (le score peut ne pas être compté). Activé par défaut.",
  "settings.n3fjp.useEnter.label": "Utiliser ENTER pour le score Field Day",
  "settings.orbitalElements.hint": "Les éléments képlériens (TLE) des satellites amateurs — horaires de passage, pointage et Doppler en découlent tous. Rafraîchis toutes les 6 h depuis hamradiotools.io : la liste des satellites vient de la base SatNOGS (CC BY-SA 4.0), les éléments de CelesTrak et SatNOGS. Importez un fichier pour un shack hors ligne ou un satellite tout juste lancé.",
  "settings.orbitalElements.import.action": "Importer depuis un fichier",
