  "settings.psk.legend": "PSK",
  "settings.psk.rxAutoArm.hint": "L'écran PSK démarre le décodeur dès que vous l'ouvrez — cliquez une trace sur la cascade et le texte s'affiche, sans réglage. Désactivez pour armer le récepteur à la main (le bouton Armer RX dans le panneau de texte décodé). Si vous arrêtez le récepteur vous-même, c'est déjà mémorisé pour le reste de la session. Ceci arme uniquement le RÉCEPTEUR — l'émission n'est jamais armée à votre place.",
  "settings.psk.rxAutoArm.label": "Démarrer la réception à l'ouverture de PSK",
  "settings.q65.hint": "Q65 émet et reçoit. La période et le sous-mode déterminent à la fois ce que vous entendez et ce que vous envoyez, et LES DEUX STATIONS DOIVENT CORRESPONDRE — un correspondant sur une autre période ou un autre sous-mode ne vous décodera pas.",
  "settings.q65.legend": "Q65 — EME / scatter VHF+",
  "settings.q65.period.deepEme": "120 s — EME difficile",
  "settings.q65.period.eme": "60 s — EME (le plus courant)",
  "settings.q65.period.hint": "Des périodes plus longues intègrent plus longtemps et entendent des signaux plus faibles, au rythme d'un échange par période. Les deux stations doivent utiliser la <b>même</b> période. Changer ceci change la longueur de trame du décodage, l'effet est donc au créneau suivant.",
  "settings.q65.period.label": "Période T/R",
  "settings.q65.period.meteor": "30 s — météores 6 m / ionoscatter",
  "settings.q65.period.microwaveEme": "300 s — le plus extrême, EME micro-ondes",
  "settings.q65.period.tropo": "15 s — troposcatter",
  "settings.q65.submode.a": "A — le plus étroit, le plus sensible",
