  "settings.q65.submode.e": "E — écart 16x, le plus tolérant au Doppler",
  "settings.q65.submode.hint": "Un écart plus large encaisse plus d'étalement Doppler et de dérive, au prix de la sensibilité. Montez dans les lettres à mesure que le chemin se dégrade — l'EME sur les bandes hautes demande en général B ou C.",
